import{_ as e,C as i,c as t,o as r,a0 as l,b as a,w as n,a as o,G as d,a1 as s}from"./chunks/framework.DKRgXLPU.js";const k=JSON.parse('{"title":"Teamkommunikation","description":"","frontmatter":{},"headers":[],"relativePath":"da/education/team-player/communication.md","filePath":"da/education/team-player/communication.md"}');const u=e({name:"da/education/team-player/communication.md"},[["render",function(e,k,u,m,g,h){const p=i("Mermaid");return r(),t("div",null,[k[1]||(k[1]=l('<h1 id="teamkommunikation" tabindex="-1">Teamkommunikation <a class="header-anchor" href="#teamkommunikation" aria-label="Permalink to &quot;Teamkommunikation&quot;">​</a></h1><p>Effektiv kommunikation er det, der forvandler en gruppe individer til et hold. I petanque, hvor strategien konstant ændrer sig, og presset er højt, kan måden, du kommunikerer på, afgøre resultatet.</p><div class="tip custom-block"><p class="custom-block-title">Den store idé</p><p><strong>Kommunikation er det, der forvandler individer til et team.</strong> Klar, specifik og støttende kommunikation under pres adskiller gode teams fra fantastiske teams.</p></div><h2 id="kommunikationscyklussen" tabindex="-1">Kommunikationscyklussen <a class="header-anchor" href="#kommunikationscyklussen" aria-label="Permalink to &quot;Kommunikationscyklussen&quot;">​</a></h2><p>God teamkommunikation følger en cyklus:</p>',5)),(r(),a(s,null,{default:n(()=>[d(p,{id:"mermaid-17",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20A%5BObservere%5D%20--%3E%20B%5BDele%5D%0A%20%20%20%20B%20--%3E%20C%5BDr%C3%B8fte%5D%0A%20%20%20%20C%20--%3E%20D%5BBeslutte%5D%0A%20%20%20%20D%20--%3E%20E%5BUdf%C3%B8r%5D%0A%20%20%20%20E%20--%3E%20F%5BAnmeldelse%5D%0A%20%20%20%20F%20--%3E%20A%0A%0A%20%20%20%20style%20A%20fill%3A%23e3f2fd%0A%20%20%20%20style%20D%20fill%3A%23e8f5e9%0A%20%20%20%20style%20E%20fill%3A%23fff4e1%0A%20%20%20%20style%20F%20fill%3A%23f3e5f5%0A"})]),fallback:n(()=>[...k[0]||(k[0]=[o(" Loading... ",-1)])]),_:1})),k[2]||(k[2]=l('<table tabindex="0"><thead><tr><th>Trin</th><th>Handling</th><th>Eksempel</th></tr></thead><tbody><tr><td><strong>Observere</strong></td><td>Læg mærke til hvad der sker</td><td>Terræn, positioner, modstandere</td></tr><tr><td><strong>Dele</strong></td><td>Fortæl dine holdkammerater, hvad du ser</td><td>&quot;Jorden skråner derfra&quot;</td></tr><tr><td><strong>Drøfte</strong></td><td>Udvekslingsperspektiver</td><td>&quot;Skal jeg blokere eller gå efter point?&quot;</td></tr><tr><td><strong>Beslutte</strong></td><td>Enig om fremgangsmåde</td><td>&quot;Lad os prøve den høje lob&quot;</td></tr><tr><td><strong>Udfør</strong></td><td>Gør det med engagement</td><td>Fuld fokus på kastet</td></tr><tr><td><strong>Anmeldelse</strong></td><td>Lær af resultatet</td><td>&quot;Det virkede godt&quot; eller &quot;Næste gang...&quot;</td></tr></tbody></table><h2 id="hvornar-skal-man-kommunikere" tabindex="-1">Hvornår skal man kommunikere <a class="header-anchor" href="#hvornar-skal-man-kommunikere" aria-label="Permalink to &quot;Hvornår skal man kommunikere&quot;">​</a></h2><h3 id="før-hver-ende" tabindex="-1">Før hver ende <a class="header-anchor" href="#før-hver-ende" aria-label="Permalink to &quot;Før hver ende&quot;">​</a></h3><ul><li>Vurder terrænet sammen</li><li>Diskuter den generelle tilgang</li><li>Afklar hvem der kaster hvornår</li><li>Sæt tonen (rolig, fokuseret)</li></ul><h3 id="under-slutningen" tabindex="-1">Under slutningen <a class="header-anchor" href="#under-slutningen" aria-label="Permalink to &quot;Under slutningen&quot;">​</a></h3><ul><li>Del observationer (&quot;Jorden hælder derfra&quot;)</li><li>Koordinatstrategi (&quot;Skal jeg forsøge at blokere eller gå efter pointen?&quot;)</li><li>Tilbyd støtte (&quot;Tag dig god tid, du klarer det&quot;)</li><li>Juster planer efterhånden som situationen ændrer sig</li></ul><h3 id="mellem-enderne" tabindex="-1">Mellem enderne <a class="header-anchor" href="#mellem-enderne" aria-label="Permalink to &quot;Mellem enderne&quot;">​</a></h3><ul><li>Kort opsummering (hvad virkede, hvad virkede ikke)</li><li>Nulstil mentalt</li><li>Gør dig klar til næste ende</li><li>Hold kontakten som et team</li></ul><h3 id="efter-kampen" tabindex="-1">Efter kampen <a class="header-anchor" href="#efter-kampen" aria-label="Permalink to &quot;Efter kampen&quot;">​</a></h3><ul><li>Fuld debriefing (hvis relevant)</li><li>Anerkend bidrag</li><li>Identificer læring</li><li>Oprethold forholdet</li></ul><h2 id="sadan-kommunikerer-du" tabindex="-1">Sådan kommunikerer du <a class="header-anchor" href="#sadan-kommunikerer-du" aria-label="Permalink to &quot;Sådan kommunikerer du&quot;">​</a></h2><h3 id="vær-klar-og-specifik" tabindex="-1">Vær klar og specifik <a class="header-anchor" href="#vær-klar-og-specifik" aria-label="Permalink to &quot;Vær klar og specifik&quot;">​</a></h3><p><strong>Vag:</strong> &quot;Prøv at komme tæt på&quot; <strong>Fjern:</strong> &quot;Sig mod venstre side af donkraften, ca. 20 cm ude&quot;</p><p><strong>Vag:</strong> &quot;Godt forsøg&quot; <strong>Tydelig:</strong> &quot;God vægt, lige lidt til venstre for linjen&quot;</p><h3 id="vær-konstruktiv" tabindex="-1">Vær konstruktiv <a class="header-anchor" href="#vær-konstruktiv" aria-label="Permalink to &quot;Vær konstruktiv&quot;">​</a></h3><p>Fokuser på løsninger, ikke problemer:</p><p><strong>Problemfokuseret:</strong> &quot;Du bliver ved med at bomme til højre&quot; <strong>Løsningsfokuseret:</strong> &quot;Måske prøve at sigte lidt mere til venstre for at kompensere?&quot;</p><h3 id="vær-støttende" tabindex="-1">Vær støttende <a class="header-anchor" href="#vær-støttende" aria-label="Permalink to &quot;Vær støttende&quot;">​</a></h3><p>Din tone er lige så vigtig som dine ord:</p><ul><li>Bevar roen, selv når du er frustreret</li><li>Brug opmuntrende kropssprog</li><li>Anerkend indsatsen, ikke kun resultaterne</li><li>Byg op, riv ikke ned</li></ul><h3 id="lyt-aktivt" tabindex="-1">Lyt aktivt <a class="header-anchor" href="#lyt-aktivt" aria-label="Permalink to &quot;Lyt aktivt&quot;">​</a></h3><p>Kommunikation er tovejs:</p><ul><li>Vær fuld opmærksomhed, når holdkammerater taler</li><li>Stil afklarende spørgsmål</li><li>Anerkend hvad du har hørt</li><li>Afbryd eller afvis ikke</li></ul><h2 id="kommunikationsudfordringer" tabindex="-1">Kommunikationsudfordringer <a class="header-anchor" href="#kommunikationsudfordringer" aria-label="Permalink to &quot;Kommunikationsudfordringer&quot;">​</a></h2><h3 id="uenighed-om-strategi" tabindex="-1">Uenighed om strategi <a class="header-anchor" href="#uenighed-om-strategi" aria-label="Permalink to &quot;Uenighed om strategi&quot;">​</a></h3><p><strong>Dårlig tilgang:</strong></p><ul><li>Insister på din vej</li><li>Vær defensiv</li><li>Giv efter vredt</li><li>Diskussion under spillet</li></ul><p><strong>Bedre fremgangsmåde:</strong></p><ol><li>Del dit perspektiv tydeligt</li><li>Lyt fuldt ud til deres</li><li>Diskuter kort fordele og ulemper</li><li>Beslut sammen (eller overlad det til den udpegede leder)</li><li>Forpligt dig fuldt ud til beslutningen</li><li>Gennemgang efter kampen</li></ol><h3 id="efter-en-holdkammerats-fejl" tabindex="-1">Efter en holdkammerats fejl <a class="header-anchor" href="#efter-en-holdkammerats-fejl" aria-label="Permalink to &quot;Efter en holdkammerats fejl&quot;">​</a></h3><p><strong>Hvad de har brug for:</strong></p><ul><li>Hurtig bekræftelse</li><li>Tilladelse til at gå videre</li><li>Tillid til, at du stadig har tillid til dem</li><li>Fokuser på det næste kast</li></ul><p><strong>Hvad skal man sige:</strong></p><ul><li>&quot;Intet problem, den næste&quot;</li><li>&quot;Hård pause, du har den næste&quot;</li><li>&quot;Vi er stadig i gang med det her&quot;</li><li><em>Nogle gange er et nik eller klap nok</em></li></ul><p><strong>Hvad man IKKE skal sige:</strong></p><ul><li>Intet (stilhed føles som dom)</li><li>&quot;Det er okay&quot; (kan lyde afvisende)</li><li>Alt om hvad der gik galt (ikke nu)</li><li>Synlig frustration (kropssprog tæller)</li></ul><h3 id="nar-du-laver-en-fejl" tabindex="-1">Når du laver en fejl <a class="header-anchor" href="#nar-du-laver-en-fejl" aria-label="Permalink to &quot;Når du laver en fejl&quot;">​</a></h3><p><strong>Hvad skal man gøre:</strong></p><ul><li>Kort takkeord (&quot;Min fejl&quot;)</li><li>Undskyld ikke for meget</li><li>Lav ikke undskyldninger</li><li>Nulstil og fokuser på næste kast</li><li>Stol på dine holdkammerater til at støtte dig</li></ul><h3 id="spænding-i-holdet" tabindex="-1">Spænding i holdet <a class="header-anchor" href="#spænding-i-holdet" aria-label="Permalink to &quot;Spænding i holdet&quot;">​</a></h3><p>Hvis spændingen opbygges under et spil:</p><ol><li>Anerkend at det sker</li><li>Tag en indånding før du svarer</li><li>Fokuser på spillet, ikke konflikten</li><li>Tag det ordentligt op efter kampen</li><li>Lad det ikke påvirke dit spil</li></ol><h2 id="nonverbal-kommunikation" tabindex="-1">Nonverbal kommunikation <a class="header-anchor" href="#nonverbal-kommunikation" aria-label="Permalink to &quot;Nonverbal kommunikation&quot;">​</a></h2><p>Meget af teamkommunikationen er nonverbal:</p><h3 id="positive-signaler" tabindex="-1">Positive signaler <a class="header-anchor" href="#positive-signaler" aria-label="Permalink to &quot;Positive signaler&quot;">​</a></h3><ul><li>Øjenkontakt</li><li>Nikker</li><li>Tommelfingeren op</li><li>Afslappet kropsholdning</li><li>Bevæger sig mod holdkammerater</li><li>Smilende (når det er passende)</li></ul><h3 id="negative-signaler-undga-disse" tabindex="-1">Negative signaler (undgå disse) <a class="header-anchor" href="#negative-signaler-undga-disse" aria-label="Permalink to &quot;Negative signaler (undgå disse)&quot;">​</a></h3><ul><li>Øjenrullende</li><li>Vender sig væk</li><li>Krydsede arme</li><li>Sukkende</li><li>Ryster på hovedet</li><li>Anspændt kropssprog</li></ul><p><strong>Husk:</strong> Dine holdkammerater ser alt. Dit kropssprog påvirker deres selvtillid og præstation.</p><h2 id="opbygning-af-kommunikationsvaner" tabindex="-1">Opbygning af kommunikationsvaner <a class="header-anchor" href="#opbygning-af-kommunikationsvaner" aria-label="Permalink to &quot;Opbygning af kommunikationsvaner&quot;">​</a></h2><h3 id="praksiskommunikation" tabindex="-1">Praksiskommunikation <a class="header-anchor" href="#praksiskommunikation" aria-label="Permalink to &quot;Praksiskommunikation&quot;">​</a></h3><p>Vent ikke på, at konkurrenterne kommunikerer:</p><ul><li>Øv strategiske diskussioner i træning</li><li>Giv hinanden feedback regelmæssigt</li><li>Udvikl dit teamsprog</li><li>Skab tryghed med ærlig samtale</li></ul><h3 id="udvikle-teamsignaler" tabindex="-1">Udvikle teamsignaler <a class="header-anchor" href="#udvikle-teamsignaler" aria-label="Permalink to &quot;Udvikle teamsignaler&quot;">​</a></h3><p>Nogle hold udvikler forkortelser:</p><ul><li>Håndsignaler til strategi</li><li>Kodeord for situationer</li><li>Hurtige sætninger med fælles betydning</li></ul><h3 id="regelmæssige-indtjekninger" tabindex="-1">Regelmæssige indtjekninger <a class="header-anchor" href="#regelmæssige-indtjekninger" aria-label="Permalink to &quot;Regelmæssige indtjekninger&quot;">​</a></h3><p>Uden for spil:</p><ul><li>Hvordan arbejder vi sammen?</li><li>Hvad går godt?</li><li>Hvad kunne være bedre?</li><li>Er der nogen problemer, der skal løses?</li></ul><h2 id="kaptajnens-rolle" tabindex="-1">Kaptajnens rolle <a class="header-anchor" href="#kaptajnens-rolle" aria-label="Permalink to &quot;Kaptajnens rolle&quot;">​</a></h2><p>Hvis dit team har en udpeget leder:</p><p><strong>Kaptajnens ansvar:</strong></p><ul><li>Endelig beslutning, når holdet er uenigt</li><li>Sætter tonen og energien</li><li>Håndtering af teamdynamik</li><li>Holder fokus under pres</li></ul><p><strong>Alle andre:</strong></p><ul><li>Del dit perspektiv</li><li>Støt beslutningen, når den er truffet</li><li>Hjælp med at bevare teamets energi</li><li>Tag ansvar for din rolle</li></ul><h2 id="vigtig-konklusion" tabindex="-1">Vigtig konklusion <a class="header-anchor" href="#vigtig-konklusion" aria-label="Permalink to &quot;Vigtig konklusion&quot;">​</a></h2><blockquote><p>Gode teams taler med hinanden, ikke om hinanden. De kommunikerer med ærlighed, respekt og et fælles engagement i succes.</p></blockquote><p>Øv kommunikation, ligesom du øver dig i at kaste. Det er en færdighed, der forbedres med opmærksomhed.</p>',68))])}]]);export{k as __pageData,u as default};
